<?php
require_once 'auth.php';
require_once 'conexion.php';
require_once 'control_parametros.php';
exigirRoles(array('ADMINISTRADOR'));
function mctlE($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function mctlCount(mysqli $c,string $t):int{$r=$c->query("SELECT COUNT(*) c FROM `$t`");return $r?(int)$r->fetch_assoc()['c']:0;}
$counts=array();foreach(array('matriz_calculos','cpus','tipos_control','subtipos_control','centrales','contactores','contactorpot','termicos','baterias','matriz_baterias','posicionamiento_encoder_permitido','rescates_opciones','rescates_componentes','ptacabina','ptapisos') as $t){$counts[$t]=mctlCount($conexion,$t);}
$tab=$_GET['tab']??'principal';
$tabs=array('principal'=>'Matriz principal','catalogos'=>'CPUs y tipos','potencias'=>'Potencias / contactores','termicos'=>'Térmicos','baterias'=>'Baterías y rescates','encoder'=>'Encoder','puertas'=>'Puertas','comunicacion'=>'Comunicación','adicionales'=>'Adicionales','dependencias'=>'Dependencias');if(!isset($tabs[$tab]))$tab='principal';

// v212: vista operativa integrada de la matriz principal. La edición profunda sigue usando
// administrar_matriz.php para reutilizar las validaciones históricas ya probadas.
$fCpu=(int)($_GET['cpu']??0);
$fTipo=(int)($_GET['tipo']??0);
$fSubtipo=(int)($_GET['subtipo']??0);
$fBuscar=trim((string)($_GET['q']??''));
$cpusLista=$conexion->query('SELECT cpu_id,cpu_name FROM cpus ORDER BY cpu_name');
$tiposLista=$conexion->query('SELECT ctrltipo_id,ctrltipo_name FROM tipos_control ORDER BY ctrltipo_id');
$subtiposLista=$conexion->query('SELECT ctrlsubtipo_id,ctrlsubtipo_name FROM subtipos_control ORDER BY ctrlsubtipo_name');
$modelosControl=$conexion->query("SELECT c.cpu_id,c.cpu_name,COALESCE(cap.activo,'SI') activo,c.velocidad_max_mmin,c.admite_encoder,b.cpu_name base_nombre,(SELECT COUNT(*) FROM matriz_calculos m WHERE m.control_cpu=c.cpu_id) filas_propias,(SELECT COUNT(*) FROM control_compatibilidades cc WHERE cc.cpu_id=c.cpu_id AND cc.activo='SI') compat_activas FROM cpus c LEFT JOIN control_cpu_capacidades cap ON cap.cpu_id=c.cpu_id LEFT JOIN cpus b ON b.cpu_id=COALESCE(NULLIF(c.cpu_matriz_base_id,0),c.cpu_id) ORDER BY c.cpu_name");
$matrizListado=null; $matrizTotal=0;
if($tab==='principal'){
  $sql="SELECT m.control_id,m.control_codigo,m.control_potenciadesde,m.control_potenciahasta,m.control_corriente,m.control_encoder,m.control_precio,
               c.cpu_name,tc.ctrltipo_name,sc.ctrlsubtipo_name,t.tension_name,co.contactor_name,cp.contactorpot_name,th.termicos_codigo,
               lp.precios_descripcion,lp.precios_costo
        FROM matriz_calculos m
        INNER JOIN cpus c ON c.cpu_id=m.control_cpu
        INNER JOIN tipos_control tc ON tc.ctrltipo_id=m.control_tipo
        INNER JOIN subtipos_control sc ON sc.ctrlsubtipo_id=m.control_subtipo
        INNER JOIN tensiones t ON t.tension_id=m.control_tension
        LEFT JOIN contactores co ON co.contactor_id=m.control_contactor
        LEFT JOIN contactorpot cp ON cp.contactorpot_id=m.control_contactorpot
        LEFT JOIN termicos th ON th.termicos_id=m.control_termicos
        LEFT JOIN lista_precios lp ON TRIM(lp.precios_codigo)=TRIM(m.control_codigo)
        WHERE 1=1";
  $types=''; $vals=array();
  if($fCpu){$sql.=' AND m.control_cpu=?';$types.='i';$vals[]=$fCpu;}
  if($fTipo){$sql.=' AND m.control_tipo=?';$types.='i';$vals[]=$fTipo;}
  if($fSubtipo){$sql.=' AND m.control_subtipo=?';$types.='i';$vals[]=$fSubtipo;}
  if($fBuscar!==''){$sql.=' AND (m.control_codigo LIKE ? OR lp.precios_descripcion LIKE ? OR c.cpu_name LIKE ? OR sc.ctrlsubtipo_name LIKE ?)';$types.='ssss';$b='%'.$fBuscar.'%';array_push($vals,$b,$b,$b,$b);}
  $sql.=' ORDER BY c.cpu_name,tc.ctrltipo_id,sc.ctrlsubtipo_name,t.tension_name,m.control_potenciadesde LIMIT 500';
  $st=$conexion->prepare($sql);
  if($types!==''){ $refs=array($types); foreach($vals as $k=>$v){$refs[]=&$vals[$k];} call_user_func_array(array($st,'bind_param'),$refs); }
  $st->execute(); $matrizListado=$st->get_result(); $matrizTotal=$matrizListado->num_rows;
}
