.main{padding:24px;max-width:1500px;margin:auto}.hero,.card{background:#fff;border:1px solid #dfe5ec;border-radius:12px;padding:16px;margin-bottom:14px}.hero h1{margin:0 0 6px}.hero p{margin:0;color:#64748b}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 14px}.tabs a{padding:8px 10px;border:1px solid #ced8e2;border-radius:8px;text-decoration:none;color:#234;background:#fff}.tabs a.on{background:#0f5f9c;color:white;border-color:#0f5f9c}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.mini{font-size:12px;color:#64748b}.kpi strong{font-size:28px;display:block}.btn{display:inline-block;text-decoration:none;border-radius:8px;padding:9px 12px;background:#0f5f9c;color:#fff;font-weight:700;margin:4px 4px 0 0}.btn.sec{background:#edf3f7;color:#234}.warn{padding:12px;border-radius:9px;background:#fff7df;border:1px solid #eed69a;color:#665116}.tech{font-family:ui-monospace,Consolas,monospace;font-size:12px;color:#52606d}.filters{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr)) auto;gap:8px;align-items:end;margin:12px 0}.filters label{font-size:12px;font-weight:700;color:#52606d}.filters select,.filters input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #ccd6df;border-radius:7px;background:#fff}.tablewrap{overflow:auto;max-height:650px;border:1px solid #dfe5ec;border-radius:9px}table.matrix{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}table.matrix th,table.matrix td{padding:7px 8px;border-bottom:1px solid #e7edf2;text-align:left}table.matrix th{position:sticky;top:0;background:#243746;color:#fff;z-index:2}table.matrix tr:hover{background:#f4f9fd}.bad{color:#b42318;font-weight:700}.good{color:#18794e;font-weight:700}.actions{display:flex;gap:5px}.btn.sm{padding:6px 8px;font-size:11px}.note{font-size:12px;color:#667085;margin-top:8px}@media(max-width:900px){.filters{grid-template-columns:1fr 1fr}}
