<form class="filters" method="get"><input type="hidden" name="tab" value="principal"><label>CPU<select name="cpu"><option value="0">Todas</option><?php if($cpusLista) while($x=$cpusLista->fetch_assoc()):?><option value="<?=(int)$x['cpu_id']?>"<?=$fCpu===(int)$x['cpu_id']?' selected':''?>><?=mctlE($x['cpu_name'])?></option><?php endwhile;?></select></label><label>Tipo<select name="tipo"><option value="0">Todos</option><?php if($tiposLista) while($x=$tiposLista->fetch_assoc()):?><option value="<?=(int)$x['ctrltipo_id']?>"<?=$fTipo===(int)$x['ctrltipo_id']?' selected':''?>><?=mctlE($x['ctrltipo_name'])?></option><?php endwhile;?></select></label><label>Subtipo<select name="subtipo"><option value="0">Todos</option><?php if($subtiposLista) while($x=$subtiposLista->fetch_assoc()):?><option value="<?=(int)$x['ctrlsubtipo_id']?>"<?=$fSubtipo===(int)$x['ctrlsubtipo_id']?' selected':''?>><?=mctlE($x['ctrlsubtipo_name'])?></option><?php endwhile;?></select></label><label>Buscar<input name="q" value="<?=mctlE($fBuscar)?>" placeholder="Código, descripción, CPU..."></label><div><button class="btn" type="submit">Filtrar</button><a class="btn sec" href="?tab=principal">Limpiar</a></div></form>
<div class="mini" style="margin-bottom:8px"><strong><?=$matrizTotal?></strong> filas mostradas · <?=$counts['matriz_calculos']?> combinaciones totales.</div><div class="tablewrap"><table class="matrix"><thead><tr><th>CPU</th><th>Tipo</th><th>Subtipo</th><th>Tensión</th><th>HP desde</th><th>HP hasta</th><th>Contactor</th><th>Cont. pot.</th><th>Térmico</th><th>Código</th><th>Base Bejerman</th><th>Acciones</th></tr></thead><tbody><?php if($matrizListado && $matrizListado->num_rows): while($r=$matrizListado->fetch_assoc()):?><tr><td><strong><?=mctlE($r['cpu_name'])?></strong></td><td><?=mctlE($r['ctrltipo_name'])?></td><td><?=mctlE($r['ctrlsubtipo_name'])?></td><td><?=mctlE($r['tension_name'])?></td><td><?=mctlE($r['control_potenciadesde'])?></td><td><?=mctlE($r['control_potenciahasta'])?></td><td><?=mctlE($r['contactor_name']?:'—')?></td><td><?=mctlE($r['contactorpot_name']?:'—')?></td><td><?=mctlE($r['termicos_codigo']?:'—')?></td><td><span class="tech"><?=mctlE($r['control_codigo'])?></span></td><td class="<?=($r['precios_costo']===null||(float)$r['precios_costo']<=0)?'bad':'good'?>"><?=($r['precios_costo']===null?'NO EXISTE':((float)$r['precios_costo']<=0?'PRECIO 0':'OK'))?></td><td><div class="actions"><a class="btn sm" href="administrar_matriz.php?editar=<?=(int)$r['control_id']?>#formulario-configuracion">Editar</a><a class="btn sec sm" href="administrar_matriz.php?duplicar=<?=(int)$r['control_id']?>#formulario-configuracion">Duplicar</a></div></td></tr><?php endwhile; else:?><tr><td colspan="12">No hay combinaciones para esos filtros.</td></tr><?php endif;?></tbody></table></div><p class="note">La edición abre el formulario técnico existente para conservar todas sus validaciones y controles de duplicados. La búsqueda y navegación ya quedan centralizadas en Matrices de Control.</p></section>
<?php elseif($tab==='catalogos'):?><section class="card"><h2>CPUs, tipos y subtipos</h2><p><a class="btn" href="mantenimiento_control_nuevo_modelo.php">+ Nuevo modelo de Control</a><a class="btn sec" href="mantenimiento_control_compatibilidades.php">Compatibilidades globales</a></p><div class="grid"><div class="kpi"><strong><?=$counts['cpus']?></strong><span>CPUs</span></div><div class="kpi"><strong><?=$counts['tipos_control']?></strong><span>tipos</span></div><div class="kpi"><strong><?=$counts['subtipos_control']?></strong><span>subtipos</span></div></div><p class="warn"><strong>v216:</strong> cada modelo existente ya puede editarse desde una vista unificada: identidad, estado, capacidades, matriz base y Tipo + Subtipo. Las filas económicas se siguen editando con el editor de matriz probado.</p><div class="tablewrap" style="margin-top:12px"><table class="matrix"><thead><tr><th>Modelo</th><th>Estado</th><th>Matriz base</th><th>Vel. máx.</th><th>Encoder</th><th>Compat.</th><th>Filas propias</th><th>Acciones</th></tr></thead><tbody><?php if($modelosControl) while($m=$modelosControl->fetch_assoc()):?><tr><td><strong><?=mctlE($m['cpu_name'])?></strong></td><td><?=mctlE($m['activo'])?></td><td><?=mctlE($m['base_nombre']?:$m['cpu_name'])?></td><td><?=mctlE($m['velocidad_max_mmin']??'—')?></td><td><?=mctlE($m['admite_encoder']??'—')?></td><td><?=(int)$m['compat_activas']?></td><td><?=(int)$m['filas_propias']?></td><td><a class="btn sm" href="mantenimiento_control_editar_modelo.php?cpu=<?=(int)$m['cpu_id']?>">Editar modelo</a><a class="btn sec sm" href="?tab=principal&cpu=<?=(int)$m['cpu_id']?>">Matriz</a></td></tr><?php endwhile;?></tbody></table></div><p><a class="btn sec" href="administrar_matriz.php#tipos">Tipos</a><a class="btn sec" href="administrar_matriz.php#subtipos">Subtipos</a></p></section>
